    if ttype == 'circle':
        cx, cy, r = p; r = r + dr; pts = []
        for a in range(360):
            t = math.radians(a)
            pts.append((round(cx + dx + r * math.cos(t)), round(cy + dy + r * math.sin(t))))
        return _thicken(pts)
    if ttype == 'ellipse':
        cx, cy, rx, ry = p; pts = []
        for a in range(360):
            t = math.radians(a)
            pts.append((round(cx + dx + rx * math.cos(t)), round(cy + dy + ry * math.sin(t))))
        return _thicken(pts)
    if ttype == 'line':
        x0, y0, x1, y1 = p; return _thicken(_bres(x0 + dx, y0 + dy, x1 + dx, y1 + dy))
    if ttype == 'rect':
        x0, y0, x1, y1 = p
        pts = (_bres(x0 + dx, y0 + dy, x1 + dx, y0 + dy) + _bres(x1 + dx, y0 + dy, x1 + dx, y1 + dy)
               + _bres(x1 + dx, y1 + dy, x0 + dx, y1 + dy) + _bres(x0 + dx, y1 + dy, x0 + dx, y0 + dy))
        return _thicken(pts)
    if ttype == 'tri':
        ax, ay, bx, by, cx, cy = p
        pts = (_bres(ax + dx, ay + dy, bx + dx, by + dy) + _bres(bx + dx, by + dy, cx + dx, cy + dy)
               + _bres(cx + dx, cy + dy, ax + dx, ay + dy))
        return _thicken(pts)
    raise ValueError(ttype)

THR = 0.40  # part-presence threshold

def match_part(edg, ttype, p):
    """Tier-2 shape finder: template-match one part near its nominal pose."""
    drs = tuple(d for d in (-2, 0, 2) if ttype != 'circle' or p[2] + d >= 2) or (0,)
    best = (0.0, 0, 0, 0)
    for dr in drs:
        for dy in (-4, -2, 0, 2, 4):
            for dx in (-4, -2, 0, 2, 4):
                t = shape_template(ttype, p, dx, dy, dr)
                if len(t) < 8: continue
                s = len(t & edg) / len(t)
                if s > best[0]: best = (s, dx, dy, dr)
    return best  # (score, dx, dy, dr); dr is a radius delta for circles

def part_center(ttype, p, dx, dy):
    if ttype in ('circle', 'ellipse'): return (p[0] + dx, p[1] + dy)
    if ttype == 'rect': return ((p[0] + p[2]) / 2 + dx, (p[1] + p[3]) / 2 + dy)
    if ttype == 'tri': return ((p[0] + p[2] + p[4]) / 3 + dx, (p[1] + p[3] + p[5]) / 3 + dy)
    if ttype == 'line': return ((p[0] + p[2]) / 2 + dx, (p[1] + p[3]) / 2 + dy)

def ascii_art(img, w=24):
    sx = W / w; sy = H / (w // 2)
    lines = []
    yy = 0
    while yy < H:
        row = ''
        xx = 0
        while xx < W:
            blk = [img[y][x] for y in range(int(yy), min(H, int(yy + sy)))
                   for x in range(int(xx), min(W, int(xx + sx)))]
            row += '#' if sum(blk) / len(blk) > 100 else '.'
            xx += sx
        lines.append(row); yy += sy
    return '\n'.join(lines)

def part_bbox(ttype, p):
    if ttype in ('circle', 'ellipse'): return (p[0]-p[2]-2, p[1]-p[2]-2, p[0]+p[2]+2, p[1]+p[2]+2)
    if ttype == 'rect': return (p[0]-2, p[1]-2, p[2]+2, p[3]+2)
    if ttype == 'tri': return (min(p[0],p[2],p[4])-2, min(p[1],p[3],p[5])-2, max(p[0],p[2],p[4])+2, max(p[1],p[3],p[5])+2)
    if ttype == 'line': return (min(p[0],p[2])-3, min(p[1],p[3])-3, max(p[0],p[2])+3, max(p[1],p[3])+3)

def shift_parts(parts, ox, oy):
    out = []
    for name, tt, p in parts:
        if tt in ('circle', 'ellipse'): q = (p[0]+ox, p[1]+oy) + p[2:]
        elif tt == 'rect': q = (p[0]+ox, p[1]+oy, p[2]+ox, p[3]+oy)
        elif tt == 'tri': q = (p[0]+ox, p[1]+oy, p[2]+ox, p[3]+oy, p[4]+ox, p[5]+oy)
        elif tt == 'line': q = (p[0]+ox, p[1]+oy, p[2]+ox, p[3]+oy)
        out.append((name, tt, q))
    return out

KX=[[-1,0,1],[-2,0,2],[-1,0,1]]
KY=[[-1,-2,-1],[0,0,0],[1,2,1]]
ET=250
THR=0.40
def draw_thing(img, ox=0, oy=0):
    draw_circle(img, 24+ox, 15+oy, 7)
    draw_tri(img, 16+ox,10+oy, 20+ox,2+oy, 23+ox,9+oy)
    draw_tri(img, 32+ox,10+oy, 28+ox,2+oy, 25+ox,9+oy)
    draw_ellipse(img, 24+ox, 32+oy, 9, 6)
    draw_line(img, 31+ox,33+oy, 39+ox,25+oy)

def arrange(c):
    return [('left ear sits above the head', c['ear-left'][1] < c['head'][1]-3),
            ('right ear sits above the head', c['ear-right'][1] < c['head'][1]-3),
            ('body hangs below the head', c['body'][1] > c['head'][1]+8),
            ('head and body vertically stacked', abs(c['head'][0]-c['body'][0]) < 8),
            ('tail trails right of the body', c['tail'][0] > c['body'][0]+3)]

PARTS=[('head', 'circle', (24, 15, 7)), ('ear-left', 'tri', (16, 10, 20, 2, 23, 9)), ('ear-right', 'tri', (32, 10, 28, 2, 25, 9)), ('body', 'ellipse', (24, 32, 9, 6)), ('tail', 'line', (31, 33, 39, 25))]

def run_here(ox=0, oy=0, noise=0, seed=7, erase=None):
    img = make_grid(); draw_thing(img, ox, oy)
    if erase:
        for _n, _t, _p in PARTS:
            if _n == erase:
                _x0, _y0, _x1, _y1 = part_bbox(_t, _p)
                for _y in range(_y0, _y1 + 1):
                    for _x in range(_x0, _x1 + 1): _put(img, _x + ox, _y + oy, BG)
    if noise:
        import random as _rr
        _rnd = _rr.Random(seed)
        for _ in range(noise): img[_rnd.randrange(H)][_rnd.randrange(W)] = FG
    edg = edge_map_k(img, KX, KY, ET)
    pres = {}; centers = {}
    for _n, _t, _p in shift_parts(PARTS, ox, oy):
        _s, _dx, _dy, _dr = match_part(edg, _t, _p)
        pres[_n] = (_s, _dx, _dy, _dr, _s >= THR)
        centers[_n] = part_center(_t, _p, _dx, _dy)
    checks = arrange(centers)
    found = all(v[4] for v in pres.values()) and all(ok for _, ok in checks)
    return img, edg, pres, checks, found

def main():
    img,edg,pres,checks,found=run_here(ox=3,oy=-2,noise=40)
    print('shifted (+3,-2), 40 noise pixels:', 'FOUND' if found else 'NOT FOUND')
    for _n,_t,_p in PARTS:
        _s,_dx,_dy,_dr,_ok=pres[_n]
        print('  %-14s score=%.3f %s' % (_n,_s,'MATCH' if _ok else 'miss'))

main()

